def login_required(f):
    @functools.wraps(f)
    def decorated(*args, **kwargs):
        if 'user_id' not in session:
            flash('Please sign in to continue.', 'info')
            return redirect(url_for('auth.login'))
        return f(*args, **kwargs)
    return decorated


def get_user_upload_folder():
    """Return per-user upload directory, creating it if it doesn't exist."""
    user_id = session.get('user_id', 'anonymous')
    user_folder = os.path.join(app.config['UPLOAD_FOLDER'], str(user_id))
    os.makedirs(user_folder, exist_ok=True)
    return user_folder


def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS



def api_error_handler(f):
    """Decorator untuk menangkap exception dan mengembalikan JSON error response."""
    @functools.wraps(f)
    def wrapper(*args, **kwargs):
        try:
            return f(*args, **kwargs)
        except Exception as e:
            print(f"[API Error] {f.__name__}: {e}")
            return jsonify({"ok": False, "error": f"Terjadi kesalahan server: {str(e)}"}), 500
    return wrapper

def _get_or_init_session(filename):
    """
    Ambil CleaningSession untuk filename.
    Jika belum ada, load dari disk dan inisialisasi.
    Secures against path traversal attacks by validating with secure_filename.
    Return: (session, error_msg)
    """
    safe_name = secure_filename(filename)
    if not safe_name or safe_name != filename:
        return None, 'Nama file tidak valid.'

    user_folder = get_user_upload_folder()
    session_key = f"{session.get('user_id', 'anonymous')}_{safe_name}"

    sess = get_session(session_key)
    if sess is not None:
        return sess, None

    base_dir = os.path.abspath(user_folder)
    filepath = os.path.abspath(os.path.join(base_dir, safe_name))
    if not filepath.startswith(base_dir):
        return None, 'Akses tidak sah.'

    if not os.path.exists(filepath):
        return None, 'File tidak ditemukan.'

    df_raw = load_data(filepath)
    if df_raw is None:
        return None, 'Gagal membaca dataset.'

    sess = reset_session(session_key, df_raw)
    return sess, None


