@app.route('/dashboard/<filename>/reporting')
@login_required
def reporting_page(filename):
    """Serve halaman reporting system dengan pilihan PDF, HTML, Excel, CSV."""
    safe_name = secure_filename(filename)
    if not safe_name or safe_name != filename:
        flash('Nama file tidak valid.', 'error')
        return redirect(url_for('upload_file'))

    ctx = _get_dashboard_context(safe_name)
    if ctx is None:
        flash('File atau data tidak dapat dimuat.', 'error')
        return redirect(url_for('upload_file'))

    return render_template('reporting.html', **ctx)


