@app.route('/api/ai-chat', methods=['POST'])
def ai_chat():
    """Proxy-free AI endpoint ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â pakai Anthropic API langsung dari server."""
    try:
        import anthropic
        data     = request.get_json()
        user_msg = data.get('message', '')
        context  = data.get('context', '')

        client = anthropic.Anthropic(api_key=os.environ.get('ANTHROPIC_API_KEY', ''), timeout=180)
        system_prompt = (
            "Kamu adalah asisten analisis data cerdas bernama DataBot untuk aplikasi "
            "DS Generator Kelompok 2. "
            "Jawab dengan bahasa yang jelas, ringkas, dan informatif. "
            f"Konteks dataset saat ini: {context}"
        )
        message = client.messages.create(
            model      = "claude-sonnet-4-20250514",
            max_tokens = 1024,
            system     = system_prompt,
            messages   = [{"role": "user", "content": user_msg}],
        )
        return jsonify({'reply': message.content[0].text})

    except ImportError:
        return jsonify({
            'reply': 'Library anthropic belum terpasang. Jalankan: pip install anthropic'
        }), 500
    except Exception as e:
        return jsonify({'reply': f'Error: {str(e)}'}), 500


# ── AI Interpretation Route ─────────────────────────────────────
_rate_limit_store = {}

@app.route('/api/interpretation/<filename>', methods=['POST'])
@login_required
def api_interpretation(filename):
    safe_name = secure_filename(filename)
    ctx = _get_dashboard_context(safe_name)
    if ctx is None:
        return jsonify({'ok': False, 'error': 'Dataset tidak ditemukan'}), 404

    lang = request.args.get('lang', 'id')
    ai_settings = get_ai_settings(session.get('user_id', 'anonymous'))

    if not ai_settings or not ai_settings.get('api_key'):
        return jsonify({'ok': False, 'error': 'no_api_key'})

    user_id = session.get('user_id', 'anonymous')
    now = time.time()
    last_req = _rate_limit_store.get(user_id, 0)
    if now - last_req < 30:
        remaining = int(30 - (now - last_req))
        return jsonify({
            'ok': False, 'error': 'quota_exceeded',
            'message': f'Tunggu {remaining} detik sebelum menghasilkan interpretasi lagi.',
            'reset_in_seconds': remaining,
        })

    _rate_limit_store[user_id] = now

    try:
        result = generate_interpretation(ctx, lang, ai_settings)
        return jsonify({'ok': True, 'data': result})
    except AIClientError as e:
        return jsonify({'ok': False, 'error': str(e)})
    except Exception as e:
        return jsonify({'ok': False, 'error': str(e)}), 500


@app.route('/api/ts-charts/<filename>')
@login_required
def api_ts_charts(filename):
    """API to get TS chart data for a specific dt_col + num_col pair."""
    dt_col = request.args.get('dt_col') or None
    num_col = request.args.get('num_col') or None
    theme = request.args.get('theme', 'dark')

    ctx = _get_dashboard_context(filename)
    if ctx is None:
        return jsonify({'ok': False, 'error': 'Cannot load dataset'}), 404

    df = None
    try:
        session_key = f"{session.get('user_id', 'anonymous')}_{secure_filename(filename)}"
        from backend.cleaning_engine import get_session
        sess = get_session(session_key)
        if sess and hasattr(sess, 'df_current'):
            df = sess.df_current
    except Exception:
        pass

    if df is None:
        return jsonify({'ok': False, 'error': 'No session data'}), 500

    dt_cols = ctx.get('dt_cols', [])
    num_cols = ctx.get('num_cols', [])

    try:
        plots, insights_list, meta = generate_ts_plots(
            df, dt_cols, num_cols, theme=theme,
            dt_col=dt_col, num_col=num_col,
        )
        return jsonify({
            'ok': True,
            'plots': plots,
            'insights': insights_list,
            'meta': meta,
        })
    except Exception as e:
        return jsonify({'ok': False, 'error': str(e)}), 500


